window.FIXTURES=window.FIXTURES||{};window.FIXTURES["methodology"]={"sections":[{"heading":"Μεθοδολογία","paragraphs":["Πώς συλλέξαμε και αναλύσαμε τα ελληνικά Μέσα για την περίοδο 1 Αυγούστου – 30 Σεπτεμβρίου 2026. Οι μετρήσεις όγκου είναι αναπαράξιμες από τη βάση· ό,τι απαιτεί ανάγνωση κωδικοποιείται από γλωσσικά μοντέλα, και λέμε ποιο μοντέλο, σε ποιο δείγμα και πόσο ελέγχθηκε."]},{"heading":"Περίοδος & πηγές","paragraphs":["Οι αναλύσεις του ιστότοπου (Θέματα, ΜΜΕ & πρόσωπα, Εκλογές, Πολεμική ρητορική, Γάζα, Ισραήλ, Γλώσσα της σύγκρουσης) καλύπτουν ακριβώς την περίοδο 1 Αυγούστου – 30 Σεπτεμβρίου 2026, με ημερομηνίες ώρας Αθήνας. Δεν συγκρίνουμε με παλαιότερα έτη· όπου υπάρχει σύγκριση, είναι Σεπτέμβριος έναντι Αυγούστου ή μέρα έναντι των προηγούμενων 14 ημερών.","Το σύνολο είναι περίπου 205.000 άρθρα από 36 ελληνικά Μέσα — εφημερίδες, τηλεοπτικούς σταθμούς, πρακτορεία και ψηφιακά Μέσα, από όλο το πολιτικό φάσμα, μαζί με τα αριστερά/εναλλακτικά Μέσα (ΕφΣυν, Documento, Αυγή, TVXS, ThePressProject).","Για συγκρίσεις όγκου χρησιμοποιούνται μόνο Μέσα που συλλέχθηκαν τουλάχιστον το 90% των ημερών. Μέσα με λιγότερα από 500 άρθρα στην περίοδο δεν εμφανίζονται ως ξεχωριστές κάρτες."]},{"heading":"Συλλογή (crawling)","paragraphs":["Ζωντανή συλλογή: ένας συλλέκτης περνά από όλες τις πηγές ανά λίγα λεπτά (ρυθμίσιμο· στην περίοδο κάθε 5 λεπτά). Για κάθε Μέσο διαβάζει πρώτα το δημόσιο RSS feed· όπου δεν υπάρχει ή δεν επαρκεί, το news sitemap των τελευταίων 25 ωρών. Τα feeds ζητούνται με ETag / Last-Modified, ώστε ένα αμετάβλητο feed να μην ξανακατεβαίνει. Αν το feed περιέχει ήδη το πλήρες κείμενο (≥ 800 χαρακτήρες), η σελίδα του άρθρου δεν ανακτάται.","Ευγένεια προς τους ιστότοπους: κάθε host έχει δικό του όριο ρυθμού (ξεκινά από 1,5 αίτημα/δευτ., ανώτατο 4, με τυχαία καθυστέρηση), που μειώνεται στο μισό σε απάντηση 429/503 και ανεβαίνει αργά μετά από 20 επιτυχίες. Το πολύ 4 ταυτόχρονα αιτήματα ανά πηγή, χρονικό όριο 15 δευτ., έως 2 MB ανά σελίδα. Μια πηγή που μας αρνείται (401/403) ή μας περιορίζει «παγώνει» με εκθετική αναμονή — έως 4 ώρες για αρνήσεις, έως 1 ώρα για όρια ρυθμού. Τα αιτήματα στέλνονται με κεφαλίδες και ελληνική γλώσσα όπως ενός κοινού browser.","Επεξεργασία: κάθε νέο URL κανονικοποιείται, ελέγχεται για διπλότυπο και μπαίνει σε ουρά (Redis/RQ), από όπου workers εξάγουν το κείμενο και το αποθηκεύουν. Κάθε κύκλος κρατά κλείδωμα, ώστε δύο κύκλοι ή ένας κύκλος και ένα backfill να μη συγκρούονται.","Συμπλήρωση κενών (backfill): για την περίοδο Αυγούστου–Σεπτεμβρίου ανακτήθηκαν εκ των υστέρων άρθρα που η ζωντανή ροή έχασε, ανά Μέσο με όποια δημόσια διαδρομή υπάρχει — μηνιαία ή αριθμημένα αρχεία sitemap (π.χ. Καθημερινή, Newsbomb, Πρώτο Θέμα, Flash), το δημόσιο WordPress API (π.χ. News247, Το Βήμα, Newsbreak), σελιδοποιημένα feeds (Newsbeast) ή διαδοχικά IDs άρθρων (Αυγή). Η ημερομηνία παίρνεται από τη σελίδα του άρθρου, γιατί το lastmod των sitemaps συχνά είναι η ώρα τελευταίας επεξεργασίας. Τα backfills τρέχουν πιο αργά (έως 1 αίτημα/δευτ. σε ιστότοπους που μας περιόρισαν)."]},{"heading":"Εξαγωγή κειμένου","paragraphs":["Το κυρίως κείμενο εξάγεται με trafilatura — bare_extraction με metadata. Πριν περάσει στην επεξεργασία γίνονται έλεγχοι: Content-Type, μέγιστο μέγεθος (2 MB), δυαδικά bytes που υποδηλώνουν μη έγκυρο ή αυτοματοποιημένο περιεχόμενο, ελάχιστο μήκος (200 χαρακτήρες).","Διπλότυπα: κανονικοποιημένο URL (χωρίς utm_*, fbclid κ.λπ.) και SHA-256 του κανονικοποιημένου κειμένου."]},{"heading":"Δύο επίπεδα: μέτρηση & κωδικοποίηση","paragraphs":["Ό,τι μετριέται — αριθμός άρθρων, μερίδια, ημέρες, ποιο Μέσο έγραψε πρώτο, ιδιοκτησία — βγαίνει ντετερμινιστικά από τη βάση (SQL) και αναπαράγεται ακριβώς.","Ό,τι απαιτεί ανάγνωση — θέμα, στάση απέναντι στην κυβέρνηση, πλαίσιο, τόνος για ένα πρόσωπο, δηλώσεις — κωδικοποιείται από γλωσσικά μοντέλα (LLM), άρθρο προς άρθρο, με κλειστές κατηγορίες. Τα μοντέλα δεν γράφουν τα συμπεράσματα της σελίδας· παράγουν ετικέτες που μετά μετράμε.","Τα μοντέλα τρέχουν μέσω OpenRouter: κυρίως Qwen 3.7 Flash και Qwen 3.5 Flash, με το Gemini 2.5 Flash ως δεύτερη γνώμη ή για τα δυσκολότερα περάσματα. Η συλλογιστική (reasoning) είναι απενεργοποιημένη ώστε κάθε απάντηση να είναι σύντομη JSON. Κάθε αποτέλεσμα αποθηκεύεται μαζί με το όνομα του μοντέλου, ώστε μια ετικέτα να μη μπλέκεται με ετικέτες άλλου μοντέλου."]},{"heading":"Θέματα, ΜΜΕ & εκλογές","paragraphs":["Οι σελίδες «Θέματα», «ΜΜΕ & πρόσωπα» και «Εκλογές» διαβάζουν την ίδια κωδικοποίηση όλων των άρθρων της περιόδου, με το Qwen 3.7 Flash. Το μοντέλο επιλέχθηκε μετά από σύγκριση με το Gemini 3 Flash σε δείγμα 72 άρθρων: 77% συμφωνία στο θέμα, 78% στη στάση, με πολύ χαμηλότερο κόστος.","Βήμα 1 — κάθε άρθρο (τίτλος και αρχή του κειμένου, 20 άρθρα ανά κλήση): θέμα, γεγονός, ενότητα, πλαίσιο (σύγκρουση, ευθύνη, οικονομία, ανθρώπινη ιστορία, ηθική, σκάνδαλο, ασφάλεια, διαδικασία), στάση απέναντι στην κυβέρνηση (επικριτική / ουδέτερη / υποστηρικτική / άνευ αντικειμένου) και γωνία. Περίπου 15.800 άρθρα είχαν ήδη κωδικοποιηθεί σε προηγούμενο δείγμα με το Qwen 3.5 Flash και επαναχρησιμοποιήθηκαν.","Βήμα 2 — θέματα και ιστορίες: οι εκατοντάδες ετικέτες θεμάτων που έδωσε το μοντέλο ενοποιούνται πρώτα από το μοντέλο και μετά ντετερμινιστικά (ορθογραφικές παραλλαγές, ομοιότητα κειμένου, χειροκίνητος πίνακας) σε 36 θέματα· ό,τι έχει κάτω από 150 άρθρα πηγαίνει στα «Άλλα». Μέσα σε κάθε θέμα, τα γεγονότα ομαδοποιούνται σε ιστορίες που διαρκούν μέρες. Θέματα όπως αθλητικά, lifestyle και καιρός δεν μετρούν στα μερίδια της πολιτικής ατζέντας.","Βήμα 3 — επτά πρόσωπα (Μητσοτάκης, Τσίπρας, Ανδρουλάκης, Γεωργιάδης, Κωνσταντοπούλου, Καρυστιανού, Νετανιάχου): για περίπου 26.600 άρθρα που τα αναφέρουν, το μοντέλο διαβάζει έως 3.000 χαρακτήρες και καταγράφει τι δήλωσαν, προς ποιον, και τον τόνο του άρθρου απέναντί τους. Κάθε παράθεμα ελέγχεται λέξη προς λέξη στο κείμενο· όσα δεν βρέθηκαν (729) διαγράφηκαν. Ο τόνος μετράει μόνο όταν το όνομα βρίσκεται πράγματι στο άρθρο.","Βήμα 4 — περιλήψεις: οι δύο προτάσεις «πώς κάλυψε το Μέσο Χ το θέμα Υ» γράφονται μόνο από τις γωνίες που κωδικοποιήθηκαν στο βήμα 1, για ζεύγη με τουλάχιστον 8 άρθρα.","Κόστος όλης της περιόδου: περίπου 12 $. Η σελίδα «Εκλογές» δεν κάνει νέες κλήσεις· συνδυάζει τη στάση του βήματος 1 και τον τόνο του βήματος 3."]},{"heading":"Έλεγχος των ετικετών AI","paragraphs":["Πρώτος έλεγχος: η στάση απέναντι στην κυβέρνηση (Οκτώβριος 2026). Πήραμε 400 άρθρα της περιόδου, 100 από κάθε ετικέτα του Qwen (επικριτικό, ουδέτερο, υποστηρικτικό, άσχετο), με τυχαία σειρά. Δύο ισχυρότερα μοντέλα άλλων εταιρειών — Gemini 3.8 Flash (Google) και Claude Sonnet 5.5 (Anthropic) — τα ξαναδιάβασαν ανεξάρτητα, ολόκληρα (έως 4.000 χαρακτήρες), με αναλυτικό ορισμό, και έπρεπε να παραθέσουν αυτούσια τη φράση που στηρίζει την κρίση τους· ελέγξαμε ότι η φράση υπάρχει στο κείμενο (99,5% και 90%). Οι δύο κριτές συμφώνησαν μεταξύ τους στο 88% (κ = 0,82). Μετράμε το Qwen μόνο στα 331 άρθρα όπου οι κριτές συμφώνησαν.","Τι βρήκαμε: το «άσχετο με την κυβέρνηση» επιβεβαιώθηκε σε 99 από 100 άρθρα. Η κατεύθυνση σχεδόν ποτέ δεν αντιστρέφεται: μόνο 2 από 149 «επικριτικά» ή «υποστηρικτικά» κρίθηκαν το αντίθετο. Το Qwen όμως υπερβάλλει: από τα «επικριτικά» επιβεβαιώθηκε το 56% (29% δεν αφορούσαν ουσιαστικά την κυβέρνηση, 14% ήταν ουδέτερα), από τα «υποστηρικτικά» το 53% (29% ουδέτερα, 17% άσχετα), από τα «ουδέτερα» το 44% (48% άσχετα).","Τι σημαίνει για τις σελίδες: αναγόμενο στο σύνολο, το Qwen βρίσκει την κυβέρνηση σε περίπου 19% των άρθρων, οι κριτές σε περίπου 14%. Το συνολικό ισοζύγιο στάσης μένει αρνητικό και στις δύο μετρήσεις (−8 έναντι −5 μονάδων), αλλά τα απόλυτα ποσοστά «επικριτικών» και «υποστηρικτικών» άρθρων είναι υπερεκτιμημένα. Δεν έχουμε ακόμη αρκετά άρθρα ανά Μέσο για να πούμε αν το σφάλμα διαφέρει από Μέσο σε Μέσο.","Η αιτία και η διόρθωση: το ίδιο Qwen, όταν διαβάζει όλο το κείμενο με τον αναλυτικό ορισμό, συμφωνεί με τους κριτές στο 81% αντί για 65%, και οι ετικέτες του επιβεβαιώνονται στο 68–79%. Η επανεκτέλεση όλης της περιόδου με αυτόν τον τρόπο είναι το επόμενο βήμα. Όριο: οι κριτές είναι επίσης μοντέλα, όχι άνθρωποι· η συμφωνία τους δείχνει συνέπεια, όχι αλήθεια. Κόστος ελέγχου: περίπου 3,6 $."]},{"heading":"Θεματικά παρατηρητήρια","paragraphs":["Κάθε παρατηρητήριο ξεκινά από υποψήφια άρθρα που εντοπίζονται με λέξεις-κλειδιά στον τίτλο και την αρχή του κειμένου· το μοντέλο αποφασίζει μετά αν το άρθρο είναι πράγματι σχετικό. Μετράμε πάντα τη διατύπωση του ίδιου του Μέσου χωριστά από ό,τι παραθέτει από άλλους: η αναπαραγωγή μιας απειλής ή μιας κατηγορίας δεν είναι ενίσχυσή της.","Πολεμική ρητορική (Ελλάδα–Τουρκία): 13.700 άρθρα με Qwen 3.5 Flash — σχετικότητα (πολλοί τίτλοι «Τουρκία» είναι εσωτερική τουρκική είδηση), κλίμακα κλιμάκωσης 0–4, ποιος μιλάει (το Μέσο ή ο παρατιθέμενος), συμβάν ή ρητορική, συλλογική απόδοση ευθύνης, ανυπόγραφοι ισχυρισμοί. Παράλληλα, ένα λεξικό λέξεων χωρίς LLM ως διασταύρωση, και οι παραβιάσεις του εναέριου χώρου από τους πίνακες του ΓΕΕΘΑ. Η ημέρα συγκρίνεται με τις 14 προηγούμενες· Σεπτέμβριος έναντι Αυγούστου με έλεγχο δύο αναλογιών.","Γάζα στον Τύπο & Η εικόνα του Ισραήλ: 4.605 υποψήφια, 2.648 για Ισραήλ–Παλαιστίνη, με Qwen 3.7 Flash — φωνές και πρώτη φωνή, κατονομασμένα θύματα, όροι στη φωνή του Μέσου, πλαίσιο, και για το Ισραήλ τόνος του συντάκτη χωριστά από το αν η είδηση είναι καλή ή κακή γι’ αυτό. Οι τίτλοι κωδικοποιούνται χωριστά (ποια πλευρά υπέστη τη βλάβη, κατονομάζεται ο δράστης, συναισθηματικές λέξεις)· σε 200 τίτλους το Qwen συμφώνησε με το Gemini 2.5 Flash σε 94% / 94% / 97%. Το αν ένα άρθρο αφορά την Ελλάδα κρίνεται από λέξεις-κλειδιά, όχι από το μοντέλο.","Η γλώσσα της σύγκρουσης: 4.228 υποψήφια, 2.517 σχετικά, με Qwen 3.5 Flash, και μόνο η διατύπωση του Μέσου. Οι «συναισθηματικές» λέξεις είναι σταθερός κατάλογος ριζών (όπως στη μελέτη του The Intercept), όχι ελεύθερη επιλογή του μοντέλου. Η τρομοκρατία κωδικοποιείται σε δεύτερο πέρασμα με Gemini 2.5 Flash, που καταγράφει τον δράστη — το μικρό μοντέλο κατέγραφε λανθασμένα την πλευρά του στόχου."]},{"heading":"Ομιλίες & φάκελος προσώπου","paragraphs":["Οι ομιλίες (π.χ. Γενική Συνέλευση ΟΗΕ) διαβάζονται από τους υπότιτλους του YouTube, με χρονοσήμανση ανά λέξη· όπου δεν υπάρχουν, η απομαγνητοφώνηση γίνεται τοπικά με Whisper. Το Qwen 3.5 Flash χωρίζει την ομιλία σε θέματα και εξάγει δηλώσεις· κάθε παράθεμα πρέπει να υπάρχει αυτούσιο στο κείμενο, αλλιώς απορρίπτεται. Η σύγκριση «τι είπε / τι αναπαρήγαγε ο ελληνικός Τύπος» βασίζεται στα άρθρα της βάσης.","Φάκελος προσώπου: δηλώσεις από τηλεοπτικές εμφανίσεις, με έλεγχο ομιλητή ώστε να μην αποδίδονται λόγια άλλων συνομιλητών. Τα πιθανά ζεύγη αντιφάσεων προτείνονται από το Gemini 2.5 Flash και ελέγχονται από άνθρωπο πριν δημοσιευτούν· είναι ενδείξεις προς έλεγχο, όχι ετυμηγορίες."]},{"heading":"Ιδιοκτησία","paragraphs":["Ο χάρτης ιδιοκτησίας ξεκινά από τα στοιχεία της Solomon και του whoownsthemedia.gr (Οκτώβριος 2024) και διορθώνεται με δημοσιεύματα (π.χ. in.gr και Newsit στην Alter Ego). Όπου η σχέση δεν επιβεβαιώνεται, το Μέσο εμφανίζεται χωρίς ιδιοκτήτη. Εμφανίζουμε μερίδια, όχι απόλυτους αριθμούς άρθρων."]},{"heading":"Αρχείο αναφοράς","paragraphs":["Η σελίδα «Παράθυρο» βασίζεται στο αρχείο 2025 – Ιουλίου 2026 και σε παλαιότερη, μη-LLM επεξεργασία: λέξεις-κλειδιά TF-IDF, αναγνώριση οντοτήτων με κανόνες και ελληνικά λεξικά, κατηγορίες με κανόνες, τοπικά embeddings σε pgvector για ομοιότητα ιστοριών και θεματικά clusters, και στάση για επιλεγμένα πρόσωπα με τοπικό μοντέλο (Ollama, Qwen 2.5 7B). Τα άρθρα Αυγούστου–Σεπτεμβρίου 2026 δεν έχουν embeddings."]},{"heading":"Όρια & επικύρωση","paragraphs":["Δεν υπάρχει ακόμη σύνολο ελέγχου με ανθρώπινη κωδικοποίηση. Οι έλεγχοι γίνονται με ισχυρότερα μοντέλα-κριτές (βλ. «Έλεγχος των ετικετών AI») και δειγματοληπτική ανάγνωση· μέχρι στιγμής έχει ελεγχθεί η στάση απέναντι στην κυβέρνηση. Η συμφωνία μοντέλων δεν αποδεικνύει ότι έχουν δίκιο.","Τα μικρά μοντέλα κάνουν λάθη σε σύντομους ή ειρωνικούς τίτλους. Ένα μέτρο που αποδείχθηκε αναξιόπιστο αποσύρεται αντί να δημοσιευτεί (π.χ. το «παρουσιάζει τους ισχυρισμούς του Ισραήλ ως γεγονός», που το μοντέλο σημείωσε σε 2 από 2.592 άρθρα).","Ο τόνος ανά Μέσο και πρόσωπο έχει βαθμολογηθεί για περίπου τις μισές αναφορές (42.700 από 86.000), μόνο για εμφανείς αναφορές (στον τίτλο ή τουλάχιστον δύο φορές). Τα ποσοστά πρέπει να διαβάζονται μαζί με το πλήθος των άρθρων.","Κενά συλλογής: όλα τα Μέσα λείπουν 5–11 Αυγούστου (διακοπή συλλογής) και τα περισσότερα 12–13 Σεπτεμβρίου· για το Skai.gr δεν βρέθηκε αρχείο για συμπλήρωση. Ορισμένα Μέσα (π.χ. Ethnos, Voria) έχουν μόνο ζωντανή ροή.","Οι σελίδες μετρούν επιλογές διατύπωσης και κάλυψης· δεν αποδίδουν προθέσεις ούτε χαρακτηρίζουν ένα Μέσο ως προπαγάνδα."]}]};
